'use strict';
const assert=(condition,message)=>{if(!condition)throw Error(message);};
function allowedNavigation(value){try{const u=new URL(value);return u.protocol==='https:'&&['boralances.boranil400.workers.dev','accounts.google.com'].includes(u.hostname)&&!u.username&&!u.password;}catch{return false;}}
function bounds(p,window){const x=Math.max(0,Math.round(Number(p.x)||0)),y=Math.max(38,Math.round(Number(p.y)||38));return {x:Math.min(x,window.width-1),y:Math.min(y,window.height-1),width:Math.max(1,Math.min(Math.round(Number(p.width)||1),window.width-x)),height:Math.max(1,Math.min(Math.round(Number(p.height)||1),window.height-y))};}
function publicProfile(user){assert(user&&typeof user.uid==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(user.uid),'The chat server did not return a valid identity.');return {provider:'boralanceschatting',uid:user.uid,name:String(user.name||user.username||'Chat account').slice(0,80),username:String(user.username||'').slice(0,24),email:String(user.email||'').slice(0,254)};}
function inputEvents(payload){assert(Array.isArray(payload.events)&&payload.events.length<=96,'Invalid chat input batch.');return payload.events.map(event=>{assert(event&&['mouseMove','mouseDown','mouseUp','mouseWheel','keyDown','keyUp','char'].includes(event.type),'Invalid chat input.');const out={type:event.type};if(event.type.startsWith('mouse')){assert(Number.isInteger(event.x)&&event.x>=0&&event.x<1280&&Number.isInteger(event.y)&&event.y>=0&&event.y<720,'Invalid pointer.');out.x=event.x;out.y=event.y;if(['mouseDown','mouseUp'].includes(event.type)){assert(['left','right','middle'].includes(event.button),'Invalid button.');out.button=event.button;out.clickCount=1;}if(event.type==='mouseWheel'){out.deltaX=Math.max(-1000,Math.min(1000,Number(event.deltaX)||0));out.deltaY=Math.max(-1000,Math.min(1000,Number(event.deltaY)||0));}}else{assert(typeof event.keyCode==='string'&&event.keyCode.length>0&&event.keyCode.length<=8,'Invalid key.');out.keyCode=event.keyCode;out.modifiers=(event.modifiers||[]).filter(x=>['shift','control','alt','meta'].includes(x)).slice(0,4);}return out;});}
module.exports={allowedNavigation,bounds,publicProfile,inputEvents};
